import unittest
from program import run

class T(unittest.TestCase):
    def test_case_00(self):
        self.assertEqual(run(['3', '1', '2']), {'n': 3, 'mean': 3.3333333333333335, 'max': 6, 'label': 'GAMMA'})
    def test_case_01(self):
        self.assertEqual(run(['10', '0', '7', 'x']), {'n': 4, 'mean': 7.5, 'max': 14, 'label': 'GAMMA'})
    def test_case_02(self):
        self.assertEqual(run([' 5 ', '-2', '8']), {'n': 3, 'mean': 4.333333333333333, 'max': 8, 'label': 'GAMMA'})
    def test_case_03(self):
        self.assertEqual(run(['4:2', '9:1', 'bad']), {'n': 3, 'mean': 10.0, 'max': 18, 'label': 'GAMMA'})
    def test_case_04(self):
        self.assertEqual(run(['12', '12', '1']), {'n': 3, 'mean': 6.333333333333333, 'max': 11, 'label': 'GAMMA'})
    def test_case_05(self):
        self.assertEqual(run(['0']), {'n': 1, 'mean': 1.0, 'max': 1, 'label': 'GAMMA'})
    def test_case_06(self):
        self.assertEqual(run(['6', '6', '6', '6']), {'n': 4, 'mean': 5.0, 'max': 10, 'label': 'GAMMA'})
    def test_case_07(self):
        self.assertEqual(run(['2', 'hello', '40']), {'n': 3, 'mean': 7.666666666666667, 'max': 15, 'label': 'GAMMA'})

if __name__ == '__main__':
